#ifndef HELIKON_BUILD_KEYS_H
#define HELIKON_BUILD_KEYS_H

#include "keys.h"

/*
 * Generated by tools/build-loader-bootloader.sh as helikon_build_keys.c.
 * The test key is generated per build and is never committed; only its public
 * half is linked into the image. A release build must replace this table with
 * the owner-controlled public key from D-20.
 */
extern const struct helikon_key_table helikon_build_key_table;

#endif
